CREATE TABLE member_sms_challenge(mobile VARCHAR(24) NOT NULL,scene VARCHAR(40) NOT NULL,code_hash VARCHAR(64) NULL,expires_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,attempts INT NOT NULL DEFAULT 0,last_sent_at DATETIME NULL,sent_date DATE NULL,daily_count INT NOT NULL DEFAULT 0,PRIMARY KEY(mobile,scene)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE member_sms_budget(budget_day DATE PRIMARY KEY,requests INT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE member_social_state(state_hash VARCHAR(64) PRIMARY KEY,provider VARCHAR(100) NOT NULL,purpose VARCHAR(16) NOT NULL,member_id BIGINT NULL,expires_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE member_social_binding(provider VARCHAR(100) NOT NULL,subject VARCHAR(200) NOT NULL,member_id BIGINT NOT NULL,PRIMARY KEY(provider,subject),UNIQUE KEY uk_member_provider(member_id,provider),FOREIGN KEY(member_id) REFERENCES member_user(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
